#!/usr/bin/env bash
# Lay a music bed under a rendered demo, mixed to sit BEHIND the picture.
#
#   add-music.sh <name> <audio-file>          your own track (mp3/wav/m4a)
#   add-music.sh <name> --mubert [genre]      a fresh royalty-free bed generated by the Mubert API
#                                              genres: educational (default) | focus | inspirational | lofi | ambient | cinematic
#
# Browsers autoplay only MUTED video, so the music has to live inside the MP4 and your
# player offers "sound on". The file is rewritten in place.
# Env: DEMO_MEDIA_DIR (default demo-out/media); for --mubert: MUBERT_COMPANY_ID, MUBERT_LICENSE_TOKEN
set -euo pipefail

NAME="${1:-}"; SRC="${2:-}"; GENRE="${3:-educational}"
[[ -z "$NAME" || -z "$SRC" ]] && { sed -n '2,10p' "$0"; exit 1; }
DIR="${DEMO_MEDIA_DIR:-demo-out/media}"
VIDEO="$DIR/$NAME.mp4"
[[ -f "$VIDEO" ]] || { echo "No such asset: $VIDEO (run render-demo.sh first)"; exit 1; }
mkdir -p demo-out/music
DUR=$(ffprobe -v error -show_entries format=duration -of csv=p=0 "$VIDEO")

if [[ "$SRC" == "--mubert" ]]; then
  : "${MUBERT_COMPANY_ID:?set MUBERT_COMPANY_ID (get API access at https://mubert.com/api)}"
  : "${MUBERT_LICENSE_TOKEN:?set MUBERT_LICENSE_TOKEN}"
  case "$GENRE" in
    educational)   PLAYLIST="6.15.10" ;; # Corporate: written to sit under a voice
    focus)         PLAYLIST="1" ;;
    inspirational) PLAYLIST="0.5.4" ;;
    lofi)          PLAYLIST="6.4.0" ;;
    ambient)       PLAYLIST="3.0" ;;
    cinematic)     PLAYLIST="0.8.1" ;;
    *) echo "genre: educational | focus | inspirational | lofi | ambient | cinematic"; exit 1 ;;
  esac
  echo "→ Mubert: registering a customer"
  RESP=$(curl -sS -X POST "https://music-api.mubert.com/api/v3/service/customers" \
    -H "Content-Type: application/json" -H "company-id: $MUBERT_COMPANY_ID" -H "license-token: $MUBERT_LICENSE_TOKEN" \
    -d "{\"custom_id\":\"demo-video-$(date +%s)\"}")
  read -r CID TOK < <(printf '%s' "$RESP" | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{try{const d=JSON.parse(s).data;console.log(d.id,d.access.token)}catch{console.log("")}})')
  [[ -z "${CID:-}" || -z "${TOK:-}" ]] && { echo "Mubert returned no customer:"; printf '%s\n' "$RESP" | head -c 400; exit 1; }
  # The endpoint is a continuous stream, not a file: capture exactly as long as the clip.
  BED="demo-out/music/$NAME-$GENRE.mp3"
  echo "→ Mubert: generating ${DUR%.*}s of $GENRE"
  ffmpeg -y -loglevel error -t "$(printf '%.0f' "$DUR")" \
    -i "https://stream.mubert.com/b2b/v3?customer_id=$CID&access_token=$TOK&playlist=$PLAYLIST&bitrate=128&intensity=high" \
    -acodec libmp3lame -b:a 128k "$BED"
else
  [[ -f "$SRC" ]] || { echo "No such audio file: $SRC"; exit 1; }
  BED="$SRC"
fi

# A finished track arrives around -14 LUFS, which is loud and amateur under a demo. Bring it
# down to a background level, roll off the lows, and fade so the ending reads as deliberate.
FADE_OUT=$(echo "$DUR - 2.2" | bc)
TMP="demo-out/music/$NAME.muxed.mp4"
ffmpeg -y -loglevel error -i "$VIDEO" -i "$BED" \
  -filter:a "highpass=f=90,loudnorm=I=-23:TP=-2:LRA=7,afade=t=in:st=0:d=1.6,afade=t=out:st=$FADE_OUT:d=2.2" \
  -map 0:v -map 1:a -c:v copy -c:a aac -b:a 160k -shortest -movflags +faststart "$TMP"
mv "$TMP" "$VIDEO"
echo "   $VIDEO  (music added)"
